import{_ as p,a0 as l,w as d,s as u,ao as s,I as n,x as r,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"為什麼在 Linux 中“文件夾”被稱為“目錄”？ | LCTT x X-CMD","titleTemplate":false,"description":"為什麼在 Linux 中“文件夾”被稱為“目錄”？ | LCTT (202201) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為什麼在 Linux 中“文件夾”被稱為“目錄”？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為什麼在 Linux 中“文件夾”被稱為“目錄”？ | LCTT (202201) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202201/20211229 Folder or Directory- Here-s Why Folders are Called Directories in Linux","title":"為什麼在 Linux 中“文件夾”被稱為“目錄”？","tag":"202201","desc":""},"relativePath":"202201/20211229 Folder or Directory- Here-s Why Folders are Called Directories in Linux.md","filePath":"[post].md"}'),a={name:"202201/20211229 Folder or Directory- Here-s Why Folders are Called Directories in Linux.md"};function x(m,t,f,L,T,C){const e=l("Link");return d(),u("div",null,[t[21]||(t[21]=s('<h1 id="為什麼在-linux-中-文件夾-被稱為-目錄" tabindex="-1">為什麼在 Linux 中“文件夾”被稱為“目錄”？ <a class="header-anchor" href="#為什麼在-linux-中-文件夾-被稱為-目錄" aria-label="Permalink to “為什麼在 Linux 中“文件夾”被稱為“目錄”？”">​</a></h1><p>如果你最開始使用的是 Windows 電腦，你很可能會使用“<ruby>文件夾<rt>folder</rt></ruby>”這個術語。</p><p>但當你換到 Linux 時，你會發現文件夾通常被稱為“<ruby>目錄<rt>directory</rt></ruby>”。</p><p>這可能使一些新的 Linux 用户感到困惑。你應該叫它文件夾還是目錄？它們有區別嗎？</p><p>事情是這樣的。如果你願意，你可以叫它文件夾，如果你喜歡，也可以叫它目錄。這沒有什麼區別。</p><p>但是，如果你想知道為什麼文件夾在 Linux 中被稱為目錄，這裏有一些解釋。</p><h3 id="為什麼在-linux-中文件夾被稱為目錄" tabindex="-1">為什麼在 Linux 中文件夾被稱為目錄？ <a class="header-anchor" href="#為什麼在-linux-中文件夾被稱為目錄" aria-label="Permalink to “為什麼在 Linux 中文件夾被稱為目錄？”">​</a></h3><p>在我解釋之前，讓我們回顧一下文件夾和目錄在現實世界中的用途。</p><p>在現實中，文件夾（封套）可以用來保存幾個文件（或其他項目）。而目錄則可以用來維護項目的索引，這樣你就可以找到哪個項目位於哪裏。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/folder-directory.png?resize=800%2C450&amp;ssl=1" alt="文件夾和目錄的示意"></p><p>現在，讓我們回到目錄。這個詞甚至在 Linux 存在之前就已經存在了。它來自 UNIX 時代。Linux 繼承了 UNIX 的很多東西，這只是其中的一個。</p>',11)),n("p",null,[t[1]||(t[1]=r("現在讓我告訴你一些可能讓你吃驚的事情。目錄並不是真的把文件放在裏面。目錄是一個“特殊的文件”，它知道文件在存儲中的位置（通過 ",-1)),i(e,{href:"https://linuxhandbook.com/inode-linux/"},{default:o(()=>[...t[0]||(t[0]=[r("inode",-1)])]),_:1}),t[2]||(t[2]=r("）。",-1))]),t[22]||(t[22]=n("p",null,"這就説明了為什麼它被稱為目錄。目錄用來保存項目的索引，而不用保存項目本身。Linux 和 UNIX 中的目錄並不保存它裏面的文件。它們只是記錄文件位置的信息。",-1)),n("p",null,[t[4]||(t[4]=r("如果你想了解更多關於它的信息，我這篇關於 ",-1)),i(e,{href:"https://linuxhandbook.com/hard-link/"},{default:o(()=>[...t[3]||(t[3]=[r("硬鏈接",-1)])]),_:1}),t[5]||(t[5]=r(" 的文章應該可以幫助你。",-1))]),t[23]||(t[23]=s('<p>那麼，為什麼它被稱為文件夾呢？依我看，這是視角的原因。當你在一個圖形環境中時，你會將事物可視化。在這裏，文件可以像頁面一樣被可視化，這些文件頁面被存儲在一個封套（文件夾）中。</p><p>當操作系統開始使用圖形元素時，我認為一些術語也相應地發生了變化，目錄 -&gt; 文件夾就是其中之一。</p><h3 id="你應該叫它文件夾還是目錄" tabindex="-1">你應該叫它文件夾還是目錄？ <a class="header-anchor" href="#你應該叫它文件夾還是目錄" aria-label="Permalink to “你應該叫它文件夾還是目錄？”">​</a></h3><p>這完全取決於你。你可以按你的習慣使用這兩個術語。</p><p>然而，如果你正在學習 Linux 命令列或經常使用它，使用目錄這個術語可能會有一點幫助。</p><p>有一些 Linux 命令，如 <code>mkdir</code>、<code>rmdir</code> 等，術語 “dir” 給出了一個提示，即這些命令與目錄有關。</p><p>同樣，許多 Linux 命令和 bash 腳本會使用選項 <code>-d</code> 表示目錄，<code>-f</code> 表示文件。</p><p>甚至終端中的文件屬性也會通過在目錄前面加上字母 “d” 來區分文件和文件夾（目錄）。</p><p>拿這個例子來説，我有一個名為 <code>some</code> 的文件和一個名為 <code>something</code> 的文件夾/目錄。請注意各種 Linux 命令是如何用 “dir” 或 “d” 來區分文件和目錄的。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/file-directory-commands-difference.png?resize=800%2C378&amp;ssl=1" alt="顯示文件和目錄操作之間區別的例子"></p><p>所有這些讓我覺得，在使用 Linux 命令時，使用 “目錄” 這個術語會有好處。你的潛意識會更容易將 “dir” 和 “d” 與目錄聯繫起來。</p><p>再説一次，你想叫它文件夾或目錄這完全取決於你。人們會明白你指的是什麼。</p><p>我剛剛對目錄一詞的歷史淵源做了一些分析，這應該會給你一些提示，為什麼人們説 “在 Linux/UNIX 中，所有東西都是一個文件”。</p><p>現在我結束了我的胡言亂語，我請你對它進行評論。如果你發現任何技術上的不準確之處，請告訴我。</p><hr>',15)),n("p",null,[t[7]||(t[7]=r("via: ",-1)),i(e,{href:"https://itsfoss.com/folder-directory-linux/"},{default:o(()=>[...t[6]||(t[6]=[r("https://itsfoss.com/folder-directory-linux/",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=r("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...t[8]||(t[8]=[r("Abhishek Prakash",-1)])]),_:1}),t[13]||(t[13]=r(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[9]||(t[9]=[r("lujun9972",-1)])]),_:1}),t[14]||(t[14]=r(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[10]||(t[10]=[r("wxy",-1)])]),_:1}),t[15]||(t[15]=r(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[r("wxy",-1)])]),_:1})]),n("p",null,[t[18]||(t[18]=r("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[16]||(t[16]=[r("LCTT",-1)])]),_:1}),t[19]||(t[19]=r(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:o(()=>[...t[17]||(t[17]=[r("Linux中國",-1)])]),_:1}),t[20]||(t[20]=r(" 榮譽推出",-1))])])}const D=p(a,[["render",x]]);export{g as __pageData,D as default};
